"use strict";
const hot = module.hot;
// Dispose precedes replacement code: errors raised by that code must remain visible.
hot?.addStatusHandler((status) => {
    if (status === "dispose") {
        window.dispatchEvent(new Event("emergent-overlay:beforeUpdate"));
    }
});
